    public static void test_overall_discard_matches_both_attributes() {
        /*
         * regression: discard tokens must match whichever of id/class carries them, regardless of attribute order in
         * the source (re:test(@id|@class,...) alone only tests the source-FIRST one). Exception: 'cookie' stays
         * first-attribute-only -- pages about cookies carry it on real content.
         */
        var discarded = partial(_xpath_hits, xp.OVERALL_DISCARD_XPATH);
        assert discarded("class=\"x\" id=\"author-box\""); // token in @id, class written first
        assert discarded("id=\"x\" class=\"sidebar\""); // token in @class, id written first
        assert !discarded("class=\"hidden-x\" id=\"cookieBanner\""); // cookie exception: class-first protects
    }

