    public static void test_extract_deep_caller_supplied_tree() {
        /* Caller-supplied trees have no depth cap, so the content walk must not recurse. */
        var tree = html.fromstring("<html><body><p>root text</p></body></html>");
        var node = tree.indexOf("body");
        for (int _ = 0; _ < 3000; _++) {
            node = new etree.SubElement(node, "div");
        }
        node.text = "Deep text long enough to be kept by the extractor, appearing at the very bottom.";
        String /* nullable */ result = extract(tree, /* config = */ ZERO_CONFIG);
        assert result.contains("Deep text long enough");
    }

    public static void test_extract_leaves_caller_tree_intact() {
        /* A caller-supplied tree must come back unchanged, prune_xpath included. */
        var tree = html.fromstring("<html><body><p>First paragraph.</p><p>Second paragraph.</p></body></html>");
        var before = html.tostring(tree);
        String /* nullable */ result = extract(tree, /* prune_xpath = */ "//p[1]", /* config = */ ZERO_CONFIG);
        assert result != null;
        assert !result.contains("First paragraph");
        assert html.tostring(tree) == before;
    }

